@notation(chain({A_{i}}, " × "))
structure CartesianProduct<n: Int, for i in 1..n [A_{i}: Set<Any>]>: Set<Any> {
    laws {
        def {
            forall x_{i} in A_{i} |- [x_{i}] in self
        }
    }
}

structure Relation<A B: Set<Any>>: Set<Any> {
    laws {
        subset {
            |- Subset(self, CartesianProduct<[A, B]>)
        }
    }

properties {
        well_defined: Prop {
            forall a in A,
            exists unique b in B
            |- { [a b] in self; }
        }
    }

